class ReschedulePayload(BaseModel):
    cron_expression: str

@router.patch("/api/v1/scheduler/cron-jobs/{job_id}/reschedule")
def reschedule_cron_task(
    job_id: str,
    payload: ReschedulePayload,
    scheduler: AsyncIOScheduler = Depends(get_scheduler),
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    cron_record = db.query(TenantScheduledJob).filter(
        TenantScheduledJob.job_id == job_id,
        TenantScheduledJob.tenant_id == current_user.tenant_id
    ).first()
    if not cron_record:
        raise HTTPException(status_code=404, detail="Scheduler job not found or unauthorized")
    job = scheduler.get_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Scheduler job not found")
    minute, hour, dom, month, dow = payload.cron_expression.split()
    scheduler.reschedule_job(
        job_id,
        trigger=CronTrigger(minute=minute, hour=hour, day=dom, month=month, day_of_week=dow)
    )
    cron_record.cron_expression = payload.cron_expression
    db.commit()
    return {"status": "rescheduled", "job_id": job_id, "cron": payload.cron_expression}
